class TestErrorHandling:
    """Validate robust error handling for invalid operations."""

    def test_factory_raising_exception(self, mock_registry):
        """Factory exceptions propagate with context."""
        def broken_factory(seed, **kwargs):
            raise RuntimeError("factory failure")

        mock_registry.register("broken", broken_factory)
        with pytest.raises(RuntimeError, match="factory failure"):
            mock_registry.create("broken")

    def test_factory_returning_none(self, mock_registry):
        """Factory returning None is rejected."""
        def none_factory(seed, **kwargs):
            return None

        mock_registry.register("none", none_factory)
        with pytest.raises(ValueError, match="factory returned None"):
            mock_registry.create("none")

    def test_factory_returning_non_object(self, mock_registry):
        """Factory returning primitive is accepted but tracked."""
        def primitive_factory(seed, **kwargs):
            return seed

        mock_registry.register("primitive", primitive_factory)
        result = mock_registry.create("primitive")
        assert result == 42

    def test_create_with_unknown_kwargs(self, registered_registry):
        """Unknown kwargs are passed through without error."""
        instance = registered_registry.create("user", unexpected="value")
        assert instance["kwargs"]["unexpected"] == "value"

    def test_registry_thread_safety(self, sample_factory):
        """Concurrent registration and creation is safe."""
        reg = MockRegistry(seed=42)
        errors = []

        def worker(name):
            try:
                for i in range(50):
                    reg.register(f"type_{name}_{i}", sample_factory)
                    reg.create(f"type_{name}_{i}")
            except Exception as e:
                errors.append(e)

        threads = [threading.Thread(target=worker, args=(f"t{i}",)) for i in range(4)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert not errors, f"Thread safety violations: {errors}"
        assert len(reg._factories) == 200
        assert len(reg._instances) == 200


