class TestDeterministicContext:
    """Validate context manager behavior and isolation."""

    def test_context_enters_and_exits(self):
        """Context manager enters and exits cleanly."""
        with deterministic_context(seed=42) as ctx:
            assert ctx is not None
        # No exception means clean exit

    def test_context_sets_seed(self, sample_factory):
        """Context manager sets deterministic seed for factories."""
        with deterministic_context(seed=123) as ctx:
            ctx.register("item", sample_factory)
            result1 = ctx.create("item")
        with deterministic_context(seed=123) as ctx2:
            ctx2.register("item", sample_factory)
            result2 = ctx2.create("item")
        assert result1 == result2

    def test_context_isolation(self, sample_factory):
        """Contexts do not share state."""
        with deterministic_context(seed=1) as ctx:
            ctx.register("item", sample_factory)
            ctx.create("item")
            assert "item" in ctx._factories

        with deterministic_context(seed=2) as ctx2:
            assert "item" not in ctx2._factories

    def test_context_restores_global_state(self):
        """Context manager restores global RNG state on exit."""
        random.seed(100)
        before = random.getstate()

        with deterministic_context(seed=42):
            random.random()  # Mutate state

        after = random.getstate()
        assert before == after  # State restored

    def test_context_nested(self, sample_factory):
        """Nested contexts maintain isolation."""
        with deterministic_context(seed=1) as outer:
            outer.register("item", sample_factory)
            outer.create("item")

            with deterministic_context(seed=2) as inner:
                inner.register("item", sample_factory)
                inner.create("item")
                assert len(inner._instances["item"]) == 1

            assert len(outer._instances["item"]) == 1

    def test_context_exception_cleanup(self):
        """Context manager cleans up on exception."""
        with pytest.raises(ValueError):
            with deterministic_context(seed=42):
                raise ValueError("test failure")
        # No leaked state


