class TestPropertyBased:
    """Validate invariants across random inputs."""

    def test_registry_invariants(self, sample_factory):
        """Registry maintains invariants across operations."""
        import hypothesis
        from hypothesis import given, strategies as st

        @given(st.integers(min_value=0, max_value=1000))
        def check_invariant(seed):
            reg = MockRegistry(seed=seed)
            reg.register("item", sample_factory)
            inst = reg.create("item")
            assert inst["seed"] == seed
            assert "value" in inst
            assert 0 <= inst["value"] <= 1000

        check_invariant()

    def test_snapshot_consistency(self, sample_factory):
        """Snapshot reflects actual registry state."""
        import hypothesis
        from hypothesis import given, strategies as st

        @given(st.integers(min_value=0, max_value=100))
        def check_snapshot(count):
            reg = MockRegistry(seed=42)
            reg.register("item", sample_factory)
            for _ in range(count):
                reg.create("item")
            snap = reg.snapshot()
            assert len(snap["instances"]["item"]) == count

        check_snapshot()


