class TestChaosEngineering:
    """Validate behavior under injected failures."""

    def test_factory_failure_does_not_corrupt_registry(self, mock_registry):
        """Failed factory creation doesn't corrupt registry state."""
        def flaky_factory(seed, **kwargs):
            if random.random() < 0.5:
                raise RuntimeError("flaky failure")
            return {"seed": seed}

        mock_registry.register("flaky", flaky_factory)
        successes = 0
        failures = 0
        for _ in range(20):
            try:
                mock_registry.create("flaky")
                successes += 1
            except RuntimeError:
                failures += 1

        assert successes + failures == 20
        assert len(mock_registry._instances["flaky"]) == successes

    def test_registry_survives_exception_storm(self, sample_factory):
        """Registry remains functional after many exceptions."""
        reg = MockRegistry(seed=42)
        reg.register("good", sample_factory)
        reg.register("bad", lambda seed, **kw: (_ for _ in ()).throw(ValueError("bad")))

        for _ in range(10):
            with pytest.raises(ValueError):
                reg.create("bad")
            # Registry still works
            result = reg.create("good")
            assert result["seed"] == 42

    def test_concurrent_failure_isolation(self, sample_factory):
        """Concurrent failures don't affect other operations."""
        reg = MockRegistry(seed=42)
        reg.register("good", sample_factory)
        reg.register("bad", lambda seed, **kw: (_ for _ in ()).throw(RuntimeError("boom")))

        def bad_worker():
            for _ in range(10):
                try:
                    reg.create("bad")
                except RuntimeError:
                    pass

        def good_worker():
            for _ in range(10):
                result = reg.create("good")
                assert result["seed"] == 42

        threads = [
            threading.Thread(target=bad_worker),
            threading.Thread(target=good_worker),
            threading.Thread(target=bad_worker),
            threading.Thread(target=good_worker),
        ]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert len(reg._instances["good"]) == 20
        assert len(reg._instances["bad"]) == 0


