class TestMockingIntegration:
    """Validate integration with unittest.mock."""

    def test_patch_registry_method(self, mock_registry):
        """Registry methods can be patched."""
        with patch.object(mock_registry, "create", return_value={"mocked": True}):
            result = mock_registry.create("anything")
            assert result == {"mocked": True}

    def test_patch_factory(self, registered_registry):
        """Factory can be patched at runtime."""
        with patch.object(registered_registry, "_factories", {"user": lambda seed, **kw: {"patched": True}}):
            result = registered_registry.create("user")
            assert result == {"patched": True}

    def test_mock_factory_integration(self, mock_registry):
        """Mock factory works with registry."""
        mock_factory = MagicMock(return_value={"mocked": True})
        mock_registry.register("mock", mock_factory)
        result = mock_registry.create("mock")
        assert result == {"mocked": True}
        mock_factory.assert_called_once_with(seed=42)


